\newcommand{\mycube}[7]{
    \begin{scope}[shift={(#1,#2,#3)},scale=#4, line join=round]
		    \coordinate (A) at ( -1, -1, -1 );
		    \coordinate (B) at ( -1,  1, -1 );
		    \coordinate (C) at (  1,  1, -1 );
		    \coordinate (D) at (  1, -1, -1 );
		    \coordinate (A1) at ( -1, -1,  1 );
		    \coordinate (B1) at ( -1,  1,  1 );
		    \coordinate (C1) at (  1,  1,  1 );
		    \coordinate (D1) at (  1, -1,  1 );

            \tikzstyle{redfill1} = [color=#5!15, fill, fill opacity=#6, opacity=#6]
            \tikzstyle{redfill2} = [color=#5!40, fill, fill opacity=#6, opacity=#6]
            \tikzstyle{redfill3} = [color=#5!60, fill, fill opacity=#6, opacity=#6]

            \tkzDrawPolygon[redfill1](A1,B1,C1,D1)
            \tkzDrawPolygon[redfill2](C,C1,B1,B)
            \tkzDrawPolygon[redfill3](C,C1,D1,D)

            \coordinate (F) at (  -1, -1,  0.15 );

            \tkzDrawSegments[very thick,color=#5!](A1,B1 B1,C1 C1,D1 A1,D1 B,B1 C,C1 D,D1 B,C C,D)
            \tkzDrawSegments[color=#5](F,A1)

           \tkzDrawSegments[dashed,color=#5](A,B A,D F,A)
           \tkzLabelSegment[below](C,D){#7}

    \end{scope}
}

