		\coordinate (A) at (0,0,0);
		\coordinate (B) at (#1,0,0);
		\coordinate (C) at (#1,-#2,0);
		\coordinate (D) at (0,-#2,0);
		\coordinate (E) at (0,0,#3);
		\coordinate (F) at (#1,0,#3);
		\coordinate (H) at (0,-#2,#3);
